  `is_deleted` int NOT NULL DEFAULT '0' COMMENT '逻辑删除：0代表未删除，1代表删除',
  `is_public` int DEFAULT NULL COMMENT '是否公开所有用户，老师为所有班级，管理员为所有用户',
