DROP TABLE IF EXISTS `t_option`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_option` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id   选项答案表',
  `qu_id` int NOT NULL COMMENT '试题id',
  `is_right` int DEFAULT NULL COMMENT '是否正确',
  `image` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '选项图片（单张 URL 或多张以 ### 拼接）',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '选项内容（简答题参考答案可为含多图的 HTML）',
  `analysis` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '该选项答案解析（HTML，可内嵌多图；刷题预习接口不返回）',
  `sort` int DEFAULT NULL COMMENT '排序',
  `is_deleted` int NOT NULL DEFAULT '0' COMMENT '逻辑删除：0代表未删除，1代表删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4070 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

